//! L3: frame-by-frame replay of neutral scenarios against pinned Pokémon Showdown output.
//!
//! Every `tests/fixtures/cases/<id>.json` with a sibling `<id>.showdown.json` (generated by
//! `tools/oracle-node/src/showdown.mjs`) is compiled, replayed with oracle-guided random
//! decisions, and compared at each request boundary. A divergence is a disagreement to
//! classify (TESTING.md §1); the report names the first diverging frame and field.

mod support;

use std::path::PathBuf;

use serde_json::Value;
use support::{
    FAILURE_BUNDLE_FILES, Scenario, load_json, replay_against_oracle, write_failure_bundle,
};

fn root() -> PathBuf {
    PathBuf::from(env!("CARGO_MANIFEST_DIR"))
}

#[test]
fn showdown_scenarios_replay_frame_by_frame() {
    let dir = root().join("tests/fixtures/cases");
    let mut ran = 0;
    let mut failures = Vec::new();
    let mut entries: Vec<_> = std::fs::read_dir(&dir)
        .expect("cases dir")
        .map(|e| e.expect("entry").path())
        .collect();
    entries.sort();
    // `SCENARIO=<substring>` replays only the matching scenario files (debugging aid).
    let only = std::env::var("SCENARIO").ok();
    // `REPLAY_DIGESTS=<file>` writes each replay's digest — its full trace and its frames — for
    // the structural refactor's old-against-new check (DESIGN.md §48.3).
    let digests_path = std::env::var_os("REPLAY_DIGESTS").map(std::path::PathBuf::from);
    let mut digests = digests_path.as_ref().map(|_| String::new());
    for path in entries {
        let name = path.file_name().and_then(|n| n.to_str()).unwrap_or("");
        if !name.ends_with(".json") || name.ends_with(".showdown.json") {
            continue;
        }
        if only.as_deref().is_some_and(|only| !name.contains(only)) {
            continue;
        }
        let oracle_path = path.with_file_name(name.replace(".json", ".showdown.json"));
        if !oracle_path.exists() {
            continue;
        }
        let scenario: Scenario = load_json(&path);
        let oracle: Value = load_json(&oracle_path);
        let report = replay_against_oracle(&scenario, &oracle);
        ran += 1;
        if let Some(out) = digests.as_mut() {
            let replayed = format!(
                "{}\n{}",
                report.trace.join("\n"),
                serde_json::Value::from(report.rust_frames.clone())
            );
            out.push_str(&format!(
                "{} {}\n",
                scenario.id,
                pokemon_battle_engine::digest::sha256_hex(replayed.as_bytes())
            ));
        }
        println!(
            "{}: {} frames compared, {} actions replayed, {} divergence(s)",
            scenario.id,
            report.frames_compared,
            report.actions_replayed,
            report.divergences.len()
        );
        assert!(
            report.frames_compared >= 2,
            "{}: nothing compared",
            scenario.id
        );
        assert!(
            report.actions_replayed >= 1,
            "{}: no action was replayed; the guided replay never engaged",
            scenario.id
        );
        if !report.divergences.is_empty() {
            let bundle = root().join("target/oracle-failures").join(&scenario.id);
            let reproduce = format!(
                "cargo test --test showdown_oracle -- --nocapture   # scenario {}",
                scenario.id
            );
            write_failure_bundle(&bundle, &path, &oracle, &report, &reproduce)
                .expect("write failure bundle");
            failures.push(format!(
                "{} ({} frames, {} actions):\n  {}\n  bundle: {}",
                scenario.id,
                report.frames_compared,
                report.actions_replayed,
                report.divergences.join("\n  "),
                bundle.display()
            ));
        }
    }
    if let (Some(path), Some(digests)) = (&digests_path, &digests) {
        std::fs::write(path, digests).expect("the replay digests");
    }
    assert!(
        ran >= 1,
        "no scenario with oracle output under tests/fixtures/cases"
    );
    assert!(
        failures.is_empty(),
        "{} scenario(s) diverge from Showdown:\n{}",
        failures.len(),
        failures.join("\n")
    );
}

/// The failure bundle is the primary diagnostic artefact (TESTING.md §9); its layout is part of
/// the v1 contract. Exercised with a synthetic divergence on a passing scenario.
#[test]
fn failure_bundle_has_the_documented_layout() {
    let path = root().join("tests/fixtures/cases/gen9-nuzzle-tackle.json");
    let scenario: Scenario = load_json(&path);
    let oracle: Value = load_json(&path.with_file_name("gen9-nuzzle-tackle.showdown.json"));
    let mut report = replay_against_oracle(&scenario, &oracle);
    report
        .divergences
        .push("synthetic: layout self-test".into());

    let dir = root().join("target/oracle-failures/_layout_selftest");
    let _ = std::fs::remove_dir_all(&dir);
    write_failure_bundle(
        &dir,
        &path,
        &oracle,
        &report,
        "cargo test --test showdown_oracle",
    )
    .unwrap();

    for file in FAILURE_BUNDLE_FILES {
        assert!(dir.join(file).is_file(), "missing {file}");
    }
    let diff: Value = load_json(&dir.join("diff.json"));
    assert_eq!(diff["first_divergence"], "synthetic: layout self-test");
    let frames: Value = load_json(&dir.join("rust.frames.json"));
    assert_eq!(
        frames.as_array().map(Vec::len),
        Some(report.frames_compared)
    );
    let provenance: Value = load_json(&dir.join("provenance.json"));
    assert!(
        provenance["rust"]["dex_fingerprint"]
            .as_str()
            .is_some_and(|f| f.starts_with("dex:"))
    );
}
